    idx = next(i for i, a in enumerate(areas) if a["key"] == "returns") + 1
    areas.insert(idx, pay.PAYMENTS)
areas += [core.TASKS, core.WEBHOOKS]

SEV = {"high": "High", "med": "Medium", "low": "Low"}
e = html.escape

total = sum(len(a["items"]) for a in areas)
counts = {s: sum(1 for a in areas for i in a["items"] if i["sev"] == s) for s in SEV}


def pill(sev):
    return f'<span class="pill {sev}">{SEV[sev]}</span>'


def tally_rows():
    rows = []
    for a in areas:
        c = {s: sum(1 for i in a["items"] if i["sev"] == s) for s in SEV}
        rows.append(
            f'<tr><th scope="row"><a href="#{a["key"]}">{e(a["name"])}</a></th>'
            + "".join(f'<td class="num {s if c[s] else "zero"}">{c[s] or "–"}</td>' for s in SEV)
            + f'<td class="num">{len(a["items"])}</td></tr>'
        )
    rows.append(
