except ImportError:
    pay = None

areas = list(core.AREAS)
if pay:
    # payments sits after returns and refunds
    idx = next(i for i, a in enumerate(areas) if a["key"] == "returns") + 1
    areas.insert(idx, pay.PAYMENTS)
areas += [core.TASKS, core.WEBHOOKS]

SEV = {"high": "High", "med": "Medium", "low": "Low"}
e = html.escape

total = sum(len(a["items"]) for a in areas)
counts = {s: sum(1 for a in areas for i in a["items"] if i["sev"] == s) for s in SEV}


def pill(sev):
    return f'<span class="pill {sev}">{SEV[sev]}</span>'


def tally_rows():
    rows = []
    for a in areas:
        c = {s: sum(1 for i in a["items"] if i["sev"] == s) for s in SEV}
        rows.append(
            f'<tr><th scope="row"><a href="#{a["key"]}">{e(a["name"])}</a></th>'
            + "".join(f'<td class="num {s if c[s] else "zero"}">{c[s] or "–"}</td>' for s in SEV)
            + f'<td class="num">{len(a["items"])}</td></tr>'
        )
    rows.append(
        '<tr class="sum"><th scope="row">All areas</th>'
        + "".join(f'<td class="num">{counts[s]}</td>' for s in SEV)
        + f'<td class="num">{total}</td></tr>'
    )
    return "\n".join(rows)


def index_rows():
    rows = []
    order = {"high": 0, "med": 1, "low": 2}
    items = [(a, i) for a in areas for i in a["items"]]
    items.sort(key=lambda p: order[p[1]["sev"]])
    for a, i in items:
        rows.append(
            f'<tr><td class="id"><a href="#{i["id"]}">{i["id"]}</a></td>'
            f'<td>{e(i["title"])}</td><td>{pill(i["sev"])}</td>'
            f'<td class="trig">{e(i["trigger"])}</td></tr>'
        )
    return "\n".join(rows)


def entry(i):
    files = "".join(f"<li><code>{e(f)}</code></li>" for f in i["files"])
    note = f'<div class="row"><dt>Scope</dt><dd>{e(i["note"])}</dd></div>' if i.get("note") else ""
    return f"""
<article class="finding {i['sev']}" id="{i['id']}">
  <header>
    <span class="fid">{i['id']}</span>
    <h3>{e(i['title'])}</h3>
    <div class="tags">{pill(i['sev'])}<span class="trigger">{e(i['trigger'])}</span></div>
  </header>
  <p class="what">{e(i['what'])}</p>
  <dl>
    <div class="row"><dt>Observed</dt><dd>{e(i['evidence'])}</dd></div>
    <div class="row"><dt>Cause</dt><dd>{e(i['where'])}</dd></div>
    {note}
    <div class="row"><dt>Reproduce</dt><dd><ul class="files">{files}</ul></dd></div>
  </dl>
</article>"""


def area_sections():
    out = []
    for a in areas:
        intro = f'<p class="area-intro">{e(a["intro"])}</p>' if a.get("intro") else ""
        out.append(
            f'<section class="area" id="{a["key"]}"><h2>{e(a["name"])}'
            f'<span class="count">{len(a["items"])}</span></h2>{intro}'
            + "".join(entry(i) for i in a["items"])
            + "</section>"
        )
    return "\n".join(out)


