checked = list(core.CHECKED_FINE) + (list(pay.CHECKED_FINE) if pay and hasattr(pay, "CHECKED_FINE") else [])
unverified = list(getattr(core, "UNVERIFIED", [])) + (list(pay.UNVERIFIED) if pay and hasattr(pay, "UNVERIFIED") else [])

